import clsx from "clsx";
import "./entry-tree.css";

interface RouteLocalEntryTreeProps {
  entries: Array<{id: string; label: string}>;
  selectedId?: string;
}

export const RouteLocalEntryTree = ({entries, selectedId}: RouteLocalEntryTreeProps) => (
  <ul className={clsx("rt_entryTree_list", selectedId && "rt_entryTree_listHasSelection")}>
    {entries.map((entry) => (
      <li key={entry.id}>{entry.label}</li>
    ))}
  </ul>
);

.rt_entryTree_list {
  display: grid;
  gap: 0.5rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.rt_entryTree_listHasSelection {
  border-inline-start: 0.125rem solid currentColor;
  padding-inline-start: 0.5rem;
}
